 11	class hashMap {
 12	    private static final int DEFAULT_CAPACITY = 20;
 13	    private static final int EMPTY_RESULT = -1;
 14	    private static final double MAX_LOAD_FACTOR = 0.5;
 15	
 16	    hashNode[] arr;
 17	    int capacity;
 18	    int size;
 19	    final hashNode dummy;
 20	
 21	    public hashMap() {
 22	        capacity = DEFAULT_CAPACITY;
 23	        size = 0;
 24	        arr = new hashNode[capacity];
 25	        dummy = new hashNode(EMPTY_RESULT, EMPTY_RESULT);
 26	    }
 27	
 28	    private int hashCode(int key) {
 29	        return Math.floorMod(key, capacity);
 30	    }
 31	
 32	    private int findExistingIndex(int key) {
 33	        int hashIndex = hashCode(key);
 34	        int probes = 0;
 35	
 36	        while (probes < capacity) {
 37	            hashNode current = arr[hashIndex];
 38	            if (current == null) {
 39	                return EMPTY_RESULT;
 40	            }
 41	            if (current.key == key) {
 42	                return hashIndex;
 43	            }
 44	            hashIndex++;
 45	            hashIndex %= capacity;
 46	            probes++;
 47	        }
 48	
 49	        return EMPTY_RESULT;
 50	    }
 51	
 52	    private int findInsertIndex(int key) {
 53	        int hashIndex = hashCode(key);
 54	        int firstTombstone = EMPTY_RESULT;
 55	        int probes = 0;
 56	
 57	        while (probes < capacity) {
 58	            hashNode current = arr[hashIndex];
 59	            if (current == null) {
 60	                return firstTombstone != EMPTY_RESULT ? firstTombstone : hashIndex;
 61	            }
 62	            if (current.key == key) {
 63	                return hashIndex;
 64	            }
 65	            if (current.key == dummy.key && firstTombstone == EMPTY_RESULT) {
 66	                firstTombstone = hashIndex;
 67	            }
 68	            hashIndex++;
 69	            hashIndex %= capacity;
 70	            probes++;
 71	        }
 72	
 73	        return firstTombstone;
 74	    }
 75	
 76	    private void resizeIfNeeded() {
 77	        if (size < capacity * MAX_LOAD_FACTOR) {
 78	            return;
 79	        }
 80	
 81	        hashNode[] previous = arr;
 82	        capacity *= 2;
 83	        arr = new hashNode[capacity];
 84	        size = 0;
 85	
 86	        for (hashNode node : previous) {
 87	            if (node != null && node.key != dummy.key) {
 88	                insertNode(node.key, node.value);
 89	            }
 90	        }
 91	    }
 92	
 93	    void insertNode(int key, int value) {
 94	        resizeIfNeeded();
 95	
 96	        int index = findInsertIndex(key);
 97	        if (index == EMPTY_RESULT) {
 98	            return;
 99	        }
100	
101	        if (arr[index] == null || arr[index].key == dummy.key) {
102	            size++;
103	        }
104	        arr[index] = new hashNode(key, value);
105	    }
106	
107	    int deleteNode(int key) {
108	        int hashIndex = findExistingIndex(key);
109	        if (hashIndex == EMPTY_RESULT) {
110	            return EMPTY_RESULT;
111	        }
112	
113	        int deletedValue = arr[hashIndex].value;
114	        arr[hashIndex] = dummy;
115	        size--;
116	        return deletedValue;
117	    }
118	
119	    int get(int key) {
120	        int hashIndex = findExistingIndex(key);
121	        if (hashIndex == EMPTY_RESULT) {
122	            return EMPTY_RESULT;
123	        }
124	
125	        return arr[hashIndex].value;
126	    }
127	
128	    int sizeofMap() {
129	        return size;
130	    }
131	
132	    boolean isEmpty() {
133	        return size == 0;
134	    }
135	
136	    void display() {
137	        for (int i = 0; i < capacity; i++) {
138	            if (arr[i] != null && arr[i].key != dummy.key) {
139	                System.out.println(arr[i].key +
140	                " " + arr[i].value);
141	            }
142	        }
143	    }
144	
145	    public static void main(String[] args) {
146	        hashMap h = new hashMap();
147	        h.insertNode(1, 1);
148	        h.insertNode(2, 2);
149	        h.insertNode(2, 3);
150	        h.display();
151	        System.out.println(h.sizeofMap());
152	        System.out.println(h.deleteNode(2));
153	        System.out.println(h.sizeofMap());
154	        System.out.println(h.isEmpty());
155	        System.out.println(h.get(2));
156	    }
157	}
